): [React.ComponentType<HasChildren>, jest.Mock] => {
  const getScroll = () => ({ x: 0, y: getY() });
  const scrollTo = jest.fn();
  const isScrollLock = false;
  const enableScrollLock = jest.fn();
  const disableScrollLock = jest.fn();
  return [
